// --- Safety Guardrails for Thumbnail and Sandbox ---
if (typeof width === 'undefined') { var width = 1280; }
if (typeof height === 'undefined') { var height = 720; }


// --- Global Variables for Uncler M Variants ---
var uM_colors = ["#1aff00", "#00ffff", "#ffff00", "#ff00ff", "#18181b"];
var speedMult = 1.0;
var lineScale = 1.0;
var dynamicShift = 0;
var scalePulse = 1.0;
var rotAngle = 0;
var gridOffset = 0;
var uM_rot = 0;

// === Inspired by '240718a' by 'Okazz' ===
// Created as variant #2 by Uncler M
// Infused with creative algorithmic modifications.

// === Tab: mySketch ===
let colors = ['#d63230', '#f7d002', '#1A53C0', '#0D274B', '#ffffff'];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	let wid = width * 0.9;
	let c = 14;
	let w = wid / c;
	background(10, 10, 15);
	strokeWeight(width * 0.0015);
	for (let i = 0; i < c; i++) {
		for (let j = 0; j < c; j++) {
			let x = w * i + (w / 2) + ((width - wid)/2);
			let y = w * j + (w / 2) + ((width - wid)/2);
			form(x, y, w);
		}
	}
}

function draw() {
  // === Variant 2: Organic Lissajous Morph ===
  scalePulse = 1.0 + 0.25 * sin(frameCount * 0.03);
  rotAngle = frameCount * 0.015;
  push();
  translate(width/2, height/2);
  rotate(rotAngle);
  scale(scalePulse);
  translate(-width/2, -height/2);



  pop();
}

function form(x, y, w) {
	let opt = int(random(12));
	push();
	translate(x, y);
	scale(pn(), 1);
	rotate(int(random(4)) * (TAU / 4));
	noFill();
	stroke(uM_colors[2]);
	fill(random(colors));
	if (opt == 0) {
		line(w * 0.5, w * 0.5, -w * 0.5, w * 0.5);
	} else if (opt == 1) {
		line(-w / 2, w / 2, w / 2, w / 2);

		triangle(-w * 0.1, 0, -w * 0.1, w * 0.4, w * 0.1, w * 0.4);
		circle(-w * 0.1, -w * 0.1, w * 0.2);

		line(-w * 0.1, w * 0.4, -w * 0.1, w * 0.5);
		line(0, w * 0.4, 0, w * 0.5);
	} else if (opt == 2) {
		noFill();
		beginShape();
		vertex(-w * 0.5, w * 0.5);
		vertex(-w * 0.4, w * 0.5);
		vertex(-w * 0.4, w * 0.3);
		vertex(-w * 0.2, w * 0.3);
		vertex(-w * 0.2, w * 0.1);
		vertex(-w * 0, w * 0.1);
		vertex(-w * 0, -w * 0.1);
		vertex(w * 0.2, -w * 0.1);
		vertex(w * 0.2, -w * 0.3);
		vertex(w * 0.4, -w * 0.3);
		vertex(w * 0.4, -w * 0.5);
		vertex(w * 0.5, -w * 0.5);
		endShape();
	} else if (opt == 3) {
		line(-w * 0.1, -w * 0.5, -w * 0.1, w * 0.5);
		line(w * 0.1, -w * 0.5, w * 0.1, w * 0.5);
		for (let i = 0; i < 6; i++) {
			let yy = map(i, 0, 5, -w * 0.4, w * 0.4);
			line(-w * 0.1, yy, w * 0.1, yy);
		}
		line(-w * 0.3, w * 0.5, w * 0.3, w * 0.5);

	} else if (opt == 4) {
		rotate(PI);

		circle(0, -w * 0.1, w * 0.2);
		circle(0, -w * 0.3, w * 0.1);
		circle(w * 0.2, -w * 0.1, w * 0.1);
		circle(-w * 0.2, -w * 0.1, w * 0.1);
		line(0, 0, 0, w * 0.3);
		triangle(w * 0.2, w * 0.5, 0, w * 0.3, -w * 0.2, w * 0.5);
		line(-w * 0.5, w * 0.5, w * 0.5, w * 0.5);
	} else if (opt == 5) {
		line(-w * 0.5, -w * 0.5, -w * 0.1, -w * 0.5);
		line(w * 0.5, -w * 0.5, w * 0.1, -w * 0.5);
		line(w * 0.25, -w * 0.5, w * 0.25, -w * 0.3);
		line(-w * 0.25, -w * 0.5, -w * 0.25, -w * 0.3);
		rect(0, -w * 0.1, w * 0.5, w * 0.4);
		rect(w * 0.2, w * 0.4, w * 0.6, w * 0.2);
	} else if (opt == 6) {
		rect(0, 0, w * 0.4, w * 0.4);
		for (let i = 0; i < 3; i++) {
			let a = map(i, 0, 3, PI, TAU*0.75+PI);
			line(w * 0.15 * cos(a), w * 0.15 * sin(a), w * 0.3 * cos(a), w * 0.3 * sin(a));
		}
		circle(0, -w*0.3, w * 0.1);
		line(0, w*0.2, 0, w*0.5);
		line(-w*0.5, w*0.5, w*0.5, w*0.5);
	} else if (opt == 7) {
		line(w * 0.5, 0, -w * 0.5, 0);
		line(w * 0.5, w * 0.5, -w * 0.5, w * 0.5);
		for (let i = 0; i < 5; i++) {
			let xx = map(i, 0, 4, -w * 0.4, w * 0.4);
			line(xx, 0, xx, w * 0.5);
		}
	} else if (opt == 8) {
		line(-w * 0.5, -w * 0.5, -w * 0.5, w * 0.5);
		arc(-w * 0.5, 0, w * 0.7, w * 0.7, -PI / 2, PI / 2, PIE);
		line(w * 0.5, w * 0.5, -w * 0.5, w * 0.5);
		fill(random(colors));
		circle(0, w * 0.4, w * 0.2);
		fill(random(colors));
		circle(w * 0.3, w * 0.1, w * 0.4);
	} else if (opt == 9) {
		triangle(0, -w * 0.1, w * 0.1, w * 0.2, -w * 0.1, w * 0.2);
		circle(0, -w * 0.2, w * 0.2);

		line(w * 0.5, w * 0.2, -w * 0.5, w * 0.2);
		line(0, w * 0.2, -w * 0.1, w * 0.4);
		line(0, w * 0.2, w * 0.1, w * 0.4);
		line(-w * 0.5, -w * 0.5, -w * 0.5, w * 0.5);
		line(w * 0.5, -w * 0.5, w * 0.5, w * 0.5);
	} else if (opt == 10) {
		triangle(-w * 0.3, w * 0.5, 0, w * 0.2, w * 0.3, w * 0.5);
		noFill();
		arc(w * 0.5, 0, w, w, PI, PI * 1.5);
		arc(-w * 0.5, 0, w, w, PI * 1.5, TAU);
		line(0, 0, 0, w * 0.2);
		line(-w * 0.5, w * 0.5, w * 0.5, w * 0.5);

	} else if (opt == 11) {
		let st = w * 0.3
		line(-w * 0.5, -w * 0.4, w * 0.5, -w * 0.4);
		line(0, -w * 0.4, 0, -w * 0.3);
		triangle(0, -w * 0.3, w * 0.1, w * 0.1, -w * 0.1, w * 0.1);
		line(st, -w * 0.4, st, -w * 0.3);
		triangle(st, -w * 0.3, w * 0.1 + st, w * 0.25, -w * 0.1 + st, w * 0.25);
		line(-st, -w * 0.4, -st, -w * 0.3);
		triangle(-st, -w * 0.3, w * 0.1 + -st, w * 0.4, -w * 0.1 + -st, w * 0.4);
	}
	pop();
}

function pn() {
	return random() < 0.5 ? -1 : 1;
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}
